<template><Card class="s1-ui"><header class="ui-header"><div><h2>{{selected?selected.name:'配置详情'}}</h2><p v-if="selected">{{status(selected.environment)}}／{{status(selected.mode)}} · {{selected.enabled?'启用':'停用'}}</p><p v-if="selected" class="ui-meta">配置 {{selected.id}} · v{{selected.version}}</p></div><div class="ui-actions"><Button @click="back">返回配置列表</Button><Button @click="reload">重新读取</Button></div></header><PageStatus v-bind="$data" :target="pendingTarget" @recover="recover()" @retry="recover(true)" @abandon="abandon"/><template v-if="selected"><Alert type="warning" show-icon>编辑或检查会失效旧核验并停用配置；启用不是微信真实能力验证。原有效路由切换不在本批自动测试范围。</Alert><Tabs v-model="tab" :animated="false"><TabPane label="配置与核验" name="overview"><DetailSection title="账户与运行信息"><FieldRow label="配置名称" :value="selected.name"/><FieldRow label="产品族" value="微信支付平台收付通"/><FieldRow label="环境" :value="status(selected.environment)"/><FieldRow label="模式" :value="status(selected.mode)"/><FieldRow label="平台商户号（掩码）" :value="selected.providerMchidMasked"/><FieldRow label="支付AppID（掩码）" :value="selected.paymentAppIdMasked"/><FieldRow label="受控凭据" :value="selected.credentialConfigured?'已配置引用':'未配置引用'"/><FieldRow label="模拟比例上限" :value="percent(selected.mockMaxRateBps)"/><FieldRow label="本地检查" :value="status(selected.checkState)"/><FieldRow label="最近检查时间" :value="date(selected.checkedAt)"/><FieldRow label="真实能力" :value="status(selected.channelQualification)"/><FieldRow label="变更原因" :value="selected.reason" wide/></DetailSection></TabPane><TabPane label="配置版本历史" name="history"><Table :columns="columns" :data="selected.history||[]"><template slot="name" slot-scope="{row}">{{row.snapshot.name}}</template><template slot="state" slot-scope="{row}">{{status(row.snapshot.mode)}} · {{row.snapshot.enabled?'启用':'停用'}} · {{status(row.snapshot.checkState)}}</template><template slot="credentials" slot-scope="{row}">{{row.snapshot.providerMchidMasked||'未提供'}} / {{row.snapshot.paymentAppIdMasked||'未提供'}}<p class="ui-meta">受控凭据：{{row.snapshot.credentialConfigured?'已配置':'未配置'}}</p></template><template slot="time" slot-scope="{row}">{{date(row.at)}}</template></Table></TabPane></Tabs><footer class="ui-footer-actions"><Button @click="back">返回列表</Button><Button :disabled="blocked" @click="show=true">编辑配置</Button><Button :disabled="blocked" @click="execute('check')">检查并失效旧核验</Button><Button :disabled="blocked" :type="selected.enabled?'warning':'primary'" @click="execute(selected.enabled?'disable':'enable')">{{selected.enabled?'停用配置':'启用配置'}}</Button></footer></template><ChannelConfigForm :visible="show" :record="selected" :disabled="blocked" :busy="busy" :error="error" @dirty="dirty=true" @save="save" @cancel="cancel"/></Card></template>
<script>import page from './page';import PageStatus from './components/PageStatus';import DetailSection from './components/DetailSection';import FieldRow from './components/FieldRow';import ChannelConfigForm from './components/ChannelConfigForm';import {stage1Confirm} from '../confirm';export default {mixins:[page],components:{PageStatus,DetailSection,FieldRow,ChannelConfigForm},data:()=>({show:false,columns:[{title:'版本',key:'version',width:80},{title:'名称',slot:'name',minWidth:160},{title:'模式／状态',slot:'state',minWidth:180},{title:'账号／凭据摘要',slot:'credentials',minWidth:250},{title:'原因',key:'reason',minWidth:180},{title:'时间',slot:'time',minWidth:185}]}),watch:{'$route.params.id'(){this.show=false;this.reload();}},mounted(){this.reload();},methods:{reload(){return this.latest(()=>this.read('/channel-configs/'+this.$route.params.id),v=>{this.selected=v;},()=>{this.selected=null;});},async save(body){try{const result=await this.run('/channel-configs/'+this.selected.id+'/draft',body,'PUT');if(result){this.show=false;this.dirty=false;await this.reload();}}catch(_){}},cancel(){if(this.dirty)stage1Confirm({title:'放弃未保存配置？',content:'关闭不会保存配置。',onOk:()=>{this.show=false;this.dirty=false;}});else this.show=false;},async execute(action){const row=this.selected;const result=await this.command('/channel-configs/'+row.id+'/'+action,{check:'检查配置并失效旧核验',enable:'启用收付通配置',disable:'停用收付通配置'}[action],{expectedVersion:row.version},row.name+' · '+this.status(row.mode)+' · v'+row.version+'。操作可能即时影响关联资格；不会调用资金。');if(result)await this.reload();}}};</script>
